	//   outer loop: rows 'n'
	//   inner loop: columns/features 'm' (contiguous in memory)
	traverser(data, mean).template for_dims<'n'>([&](auto trav_n) {
		trav_n.for_each([&](auto s) {
			mean[s] += data[s];
		});
	});

	// Scale by 1/N.
	traverser(mean).for_each([&](auto s) {
		mean[s] *= inv_n;
	});

	// ------------------------------------------------------------------------
	// stddev[j] = sqrt( (1/N) * sum_i (data[i][j] - mean[j])^2 )
	// stddev[j] = 1.0 if stddev[j] <= eps
	// ------------------------------------------------------------------------

	// Initialize stddev to zero.
	traverser(stddev).for_each([&](auto s) {
		stddev[s] = SCALAR_VAL(0.0);
	});

	// Accumulate squared differences, again row-major.
	traverser(data, mean, stddev).template for_dims<'n'>([&](auto trav_n) {
		trav_n.for_each([&](auto s) {
			const num_t diff = data[s] - mean[s];
			stddev[s] += diff * diff;
		});
	});

	// Finalize variance, take sqrt, and apply epsilon cutoff.
	traverser(stddev).for_each([&](auto s) {
		num_t var   = stddev[s] * inv_n;
		num_t sigma = SQRT_FUN(var);
		stddev[s]   = (sigma <= eps) ? SCALAR_VAL(1.0) : sigma;
	});

	// ------------------------------------------------------------------------
	// Center and reduce the column vectors:
	//   data[i][j] = (data[i][j] - mean[j]) / (sqrt(float_n) * stddev[j])
	// We reuse sqrt_n and stddev[j] to avoid recomputing sqrt(float_n).
	// Traversal is row-major for good locality.
	// ------------------------------------------------------------------------
	traverser(data, mean, stddev).template for_dims<'n'>([&](auto trav_n) {
		trav_n.for_each([&](auto s) {
			const num_t denom = sqrt_n * stddev[s];
			data[s] = (data[s] - mean[s]) / denom;
		});
	});

	// ------------------------------------------------------------------------
	// Compute the m x m correlation matrix:
	//
	// for (i = 0; i < M-1; i++) {
	//   corr[i][i] = 1.0;
	//   for (j = i+1; j < M; j++) {
	//     corr[i][j] = 0.0;
