	//   }
	// }
	// corr[M-1][M-1] = 1.0;
	//
	// Implemented using Noarr traversers; the innermost reduction over 'n'
	// keeps the original accumulation order per (i,j) pair to preserve
	// numerical behavior, but uses a local accumulator to avoid repeated
	// loads from corr[i][j].
	// ------------------------------------------------------------------------

	const std::size_t m_len = corr | get_length<'p'>(); // number of features M

	// Views on data so that the feature index matches corr's 'p'/'q' dims.
	// data_p: dims 'n', 'p' (feature index as 'p')
	// data_q: dims 'n', 'q' (feature index as 'q')
	auto data_p = data.get_ref() ^ noarr::rename<'m', 'p'>(); // dims: 'n', 'p'
	auto data_q = data.get_ref() ^ noarr::rename<'m', 'q'>(); // dims: 'n', 'q'

	// Outer loop over i = 0 .. M-1 (dimension 'p', row index of corr).
	traverser(corr).template for_dims<'p'>([&](auto trav_p) {
		auto state_p = trav_p.state();
		const std::size_t i = noarr::get_index<'p'>(state_p);

		// Only i < M-1 participate in the nested j-loop; the last diagonal
		// element corr[M-1][M-1] is set after this traversal.
		if (i < m_len - 1) {
			// corr[i][i] = 1.0;
			corr[noarr::idx<'p', 'q'>(i, i)] = SCALAR_VAL(1.0);

			// Middle loop over j = 0 .. M-1 (dimension 'q'); we only process j > i.
			trav_p.template for_dims<'q'>([&](auto trav_pq) {
				auto state_pq = trav_pq.state();
				const std::size_t j = noarr::get_index<'q'>(state_pq);

				if (j > i) {
					num_t sum = SCALAR_VAL(0.0);

					// Inner reduction over k = 0 .. N-1 (dimension 'n').
					// The proto-structure `fix(state_pq)` fixes 'p' and 'q'
					// to the current (i, j), leaving only 'n' to be traversed.
					noarr::traverser(data_p, data_q)
						.order(noarr::fix(state_pq))
						.for_each([&](auto state_n) {
							sum += data_p[state_n] * data_q[state_n];
						});

					// Write symmetric entries: corr[i][j] and corr[j][i].
					corr[state_pq] = sum;
					corr[noarr::idx<'p', 'q'>(j, i)] = sum;
				}
			});
		}
	});

	// Final diagonal element: corr[M-1][M-1] = 1.0;
	if (m_len > 0) {
		const std::size_t last = m_len - 1;
		corr[noarr::idx<'p', 'q'>(last, last)] = SCALAR_VAL(1.0);
	}

#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t m = M;

	// input data
	num_t float_n;

	// set all relevant lengths
	auto set_lengths =
		noarr::set_length<'n'>(n) ^
		noarr::set_length<'m'>(m) ^
		noarr::set_length<'p'>(m) ^
		noarr::set_length<'q'>(m);

