		// trav_n has 'n' fixed, iterates over 'm' (row-wise, contiguous)
		trav_n.template for_each<'m'>([=](auto state) {
			// state contains 'n' and 'm'; mean ignores 'n'
			mean[state] += data[state];
		});
	});

	// Scale by 1/N
	traverser(mean).for_each([=](auto s_m) {
		mean[s_m] /= float_n;
	});

