	traverser(data, mean, stddev).template for_dims<'n'>([=](auto trav_n) {
		trav_n.template for_each<'m'>([=](auto state) {
			const num_t val = data[state] - mean[state];
			stddev[state] += val * val;
		});
	});

	// Finalize stddev per feature
	traverser(stddev).for_each([=](auto s_m) {
		stddev[s_m] /= float_n;
		stddev[s_m] = SQRT_FUN(stddev[s_m]);
		stddev[s_m] = stddev[s_m] <= eps ? SCALAR_VAL(1.0) : stddev[s_m];
	});

