	// Center and reduce the column vectors:
	//   data[i][j] = (data[i][j] - mean[j]) / (sqrt(float_n) * stddev[j])
	//
	// We use the precomputed sqrt_n to avoid recomputing sqrt(float_n)
	// for every element (a large performance gain when N,M are big).
	// ------------------------------------------------------------------------
	traverser(data, mean, stddev).template for_dims<'n'>([=](auto trav_n) {
		// trav_n has 'n' fixed; iterate over 'm' (row-wise, contiguous)
		trav_n.template for_each<'m'>([=](auto state) {
			auto &d = data[state];
			d -= mean[state];
			// Order of operations matches original: multiply then divide
			d /= (sqrt_n * stddev[state]);
		});
	});

	// ------------------------------------------------------------------------
	// Compute the m x m correlation matrix:
	//
	// for (i = 0; i < M-1; i++) {
	//   corr[i][i] = 1.0;
	//   for (j = i+1; j < M; j++) {
