	//     corr[j][i] = corr[i][j];
	//   }
	// }
	// corr[M-1][M-1] = 1.0;
	//
	// Optimizations:
	//   * Use a single multi-structure traverser over data_p, data_q, corr,
	//     instead of constructing a new traverser and applying `fix` for
	//     every (i,j) pair. This removes substantial per-pair overhead.
	//   * Accumulate into a local scalar `sum` inside the innermost loop
